import './stage3.js';
import { studio } from './app.js';
import { empty, makePreset, melodic, attach } from './project.js';

const nextUI=s=>document.querySelector(s);
let laneClipboard=null,taps=[];
function refreshTools(){const t=studio.project.tracks[studio.selected];nextUI('#tool-target').textContent='当前声部：'+t.name;for(const id of ['octave-down','octave-up'])nextUI('#'+id).disabled=!melodic(t);}
studio.subscribe(refreshTools);refreshTools();
nextUI('#copy-lane').onclick=()=>{const p=studio.project,i=studio.selected;laneClipboard={melodic:melodic(p.tracks[i]),steps:[...p.tracks[i].steps],attributes:structuredClone(p.patterns[p.pattern].attributes[i])};nextUI('#paste-lane').disabled=false;studio.toast('已复制当前段落的声部音符与表现，不包含音色');};
nextUI('#paste-lane').onclick=()=>{if(!laneClipboard)return;const p=studio.project,i=studio.selected;if(melodic(p.tracks[i])!==laneClipboard.melodic){studio.toast('请在同类型声部之间粘贴：鼓到鼓，旋律到贝斯或旋律');return;}studio.mutate(()=>{p.patterns[p.pattern].steps[i]=[...laneClipboard.steps];p.patterns[p.pattern].attributes[i]=structuredClone(laneClipboard.attributes);attach(p);});studio.toast('已粘贴声部音符，可撤销');};
nextUI('#humanize-lane').onclick=()=>{const p=studio.project,i=studio.selected;if(!p.tracks[i].steps.some(n=>n!==null)){studio.toast('当前声部没有音符');return;}studio.mutate(()=>{p.tracks[i].steps.forEach((n,s)=>{if(n!==null){const a=p.patterns[p.pattern].attributes[i][s];a.velocity=Math.max(1,Math.min(100,a.velocity+Math.floor(Math.random()*25)-12));}});});studio.toast('力度已作 ±12 的随机变化，音符位置保持原位；可撤销');};
for(const [id,delta] of [['octave-down',-12],['octave-up',12]])nextUI('#'+id).onclick=()=>{const t=studio.project.tracks[studio.selected];if(!melodic(t))return;const notes=t.steps.filter(n=>n!==null);if(!notes.length)return;if(notes.some(n=>n+delta<24||n+delta>84)){studio.toast('整体移调将超出 C1–C6，请先调整边界音符');return;}studio.mutate(()=>{t.steps.forEach((n,s)=>{if(n!==null)t.steps[s]+=delta;});});};
nextUI('#tap-tempo').onclick=()=>{const now=performance.now();if(taps.length&&now-taps.at(-1)>2000)taps=[];taps.push(now);taps=taps.slice(-7);if(taps.length<4){nextUI('#tap-status').textContent=`已点击 ${taps.length} 次 / 至少 4 次`;return;}const intervals=taps.slice(1).map((n,i)=>n-taps[i]).sort((a,b)=>a-b),ms=intervals[Math.floor(intervals.length/2)],bpm=Math.round(60000/ms);if(bpm<60||bpm>180){nextUI('#tap-status').textContent='请按 60–180 BPM 的节奏点击';return;}studio.mutate(()=>studio.project.bpm=bpm,'tap-tempo');nextUI('#tap-status').textContent=bpm+' BPM · 已应用';};

const lessons=[
 {id:'grid',cat:'rhythm',title:'16 个格子怎样数拍？',intro:'本工作台的一段是 4/4 拍的一小节，每格是十六分音符。',body:'第 1、5、9、13 格是四个正拍。先在这些位置放底鼓，再在第 5、13 格放军鼓。用嘴数「1 e & a，2 e & a」时，每个音节前进一格。',task:'载入练习，先独奏底鼓，再打开军鼓，听第 2、4 拍。',exercise:'grid'},
 {id:'offbeat',cat:'rhythm',title:'反拍：把踩镲放在空隙',intro:'鼓之间的空白，也是节奏的一部分。',body:'在四拍底鼓之间的第 3、7、11、15 格放开镲，会形成正拍与反拍的交替。试着先降低开镲音量，再增加闭镲；不要一开始把所有格子填满。',task:'练习先只有底鼓与反拍开镲；加入第 5、13 格军鼓。',exercise:'offbeat'},
 {id:'swing',cat:'rhythm',title:'摇摆不是改变速度',intro:'BPM 决定整体速度，摇摆改变成对细分音符的间隔。',body:'本应用的摇摆会延后每对十六分音符中的第二个音符。把闭镲填满 16 格，比较 0% 与 35%。变化幅度是本应用的控制量，不等于其他软件的 swing 比例。',task:'载入密集踩镲，保持 BPM 不动，只改变摇摆。',exercise:'swing'},
 {id:'expression',cat:'rhythm',title:'力度、概率、连击各做什么？',intro:'让重复的段落产生层次。',body:'力度控制单个音符强弱；概率决定该步是否触发，0% 永不触发，100% 每次触发；连击把一个步长分成最多 4 次击打。先给弱拍降低力度，再给少量装饰音设置 50% 概率。WAV 使用固定随机序列，同一工程与重复次数可以重复导出。',task:'练习在最后一拍加入装饰音；只改最后几格的概率与连击。',exercise:'expression'},
 {id:'bass',cat:'melody',title:'贝斯先从根音与留白开始',intro:'一条好用的低音线不需要很多音符。',body:'先用 C2 与 G2，也就是根音和五度。把贝斯放在底鼓附近，再移动一两个音符产生呼应。生成器中的调性和音阶只影响新生成的音符，不会自动移调现有旋律。',task:'载入练习，在钢琴卷帘中把第 7 格的 G2 提前一步。',exercise:'bass'},
 {id:'duration',cat:'melody',title:'时值与尾音的区别',intro:'一个是音符保持多久，一个是音色衰减的形状。',body:'钢琴卷帘拖动音符右侧可改变旋律时值。音色面板的尾音会进一步影响合成包络；采样在旋律声部也会受时值限制。鼓声部按击打播放。每个旋律声部的每一步只能放一个音符。',task:'载入练习，拉长第一个旋律音符，比较短音与长音。',exercise:'duration'},
 {id:'arrange',cat:'melody',title:'用 A–D 做出段落变化',intro:'编曲不只是不断加入更多声部。',body:'可以用 A 做主题、B 加装饰、C 去掉底鼓形成空隙、D 做收尾。打开串联模式，再调整播放顺序。播放中的段落切换在下一小节生效，界面会区分正在编辑与正在播放的段落。',task:'载入 Garage 预设，比较四个段落，再开启串联。',preset:'garage'},
 {id:'sample',cat:'sound',title:'采样：裁切、原音高与反向',intro:'先把音频变成一段干净、可演奏的素材。',body:'在音色与混音区选择声部并导入音频，调整起点与终点。原音高表示录音本身对应的音符；演奏音高相对它决定播放速率。鼓采样可保留默认原音高。反向播放会反转音频，裁切与淡入淡出帮助减少边界杂音。',task:'导入自己的短 WAV，先裁掉开头空白，再比较正向与反向。'},
 {id:'mix',cat:'sound',title:'混音从降低音量开始',intro:'让每个声部拥有自己的位置。',body:'先降低主音量，再逐一加入声部。用独奏定位问题，再回到完整混音。低音和底鼓可先留在中央，装饰打击乐适量左右分布。降低滤波截止频率会减少高频；延迟与混响较多时，减少密集音符有助于保持清楚。',task:'载入 Dub，先把延迟降到 0，再慢慢增加，听声音的间隙。',preset:'dub'},
 {id:'wave',cat:'sound',title:'波形与音色：一次只改一项',intro:'相同音高也可以有不同质感。',body:'在贝斯或旋律声部比较正弦、三角、锯齿和方波。切换时保持音高、音量与尾音相同。这里是简化合成器；音色还会受到滤波、失真和音符表现的共同影响。使用外部采样时，波形选择不会改变采样本身。',task:'载入 Electro，独奏贝斯，再切换四种波形。',preset:'electro'},
 {id:'backup',cat:'workflow',title:'保存、工程与 WAV 怎样选择？',intro:'工程可继续编辑；WAV 用于播放和分享。',body:'自动保存和工程库保存在当前设备的浏览器中。导出 JSON 工程会包含段落、音色、效果与采样，适合备份和转移。WAV 是混音后的音频，不能恢复成各声部音符。清除浏览器数据前务必导出工程；在线版与离线版之间需要手动导入。',task:'给作品命名，保存副本，再分别导出 JSON 与 WAV。'},
 {id:'shortcuts',cat:'workflow',title:'操作速查与声音排查',intro:'少找按钮，多听变化。',body:'空格播放或暂停；A S D F G H J K 演奏八个声部；Ctrl/⌘ Z 撤销，Ctrl/⌘ Shift Z 重做。Shift 点击格子只选中。卷帘内可复制、粘贴、删除与上下移调。没有声音时先点播放，检查主音量、静音、独奏与系统输出；保持页面在前台。',task:'先用演奏垫确认声音，再开启录入并播放一段。'}
];
const categoryNames={rhythm:'节奏',melody:'旋律',sound:'音色与混音',workflow:'操作与备份'};
let learningState={saved:[],done:[]};try{const stored=JSON.parse(localStorage.getItem('groovebox.learning.v1'));for(const key of ['saved','done'])if(Array.isArray(stored?.[key]))learningState[key]=stored[key].filter(id=>lessons.some(l=>l.id===id));}catch{}
function saveLearning(){try{localStorage.setItem('groovebox.learning.v1',JSON.stringify(learningState));}catch{studio.toast('学习标记无法保存，工程可另行导出备份');}}
function exerciseProject(kind){const p=empty();p.name='练习 · '+lessons.find(l=>l.exercise===kind).title;const put=(track,steps,pitch=60)=>steps.forEach(s=>p.tracks[track].steps[s]=pitch);put(0,[0,4,8,12]);p.bpm=100;
 if(kind==='grid')put(1,[4,12]);
 if(kind==='offbeat')put(4,[2,6,10,14]);
 if(kind==='swing'){put(1,[4,12]);put(3,Array.from({length:16},(_,i)=>i));}
 if(kind==='expression'){put(1,[4,12,14,15]);put(3,[0,2,4,6,8,10,12,14]);p.patterns[0].attributes[1][14]={velocity:45,probability:50,ratchet:2,duration:1};p.patterns[0].attributes[1][15]={velocity:65,probability:70,ratchet:3,duration:1};}
 if(kind==='bass'){put(6,[0,8],36);put(6,[6,14],43);}
 if(kind==='duration'){put(7,[0,8],60);p.tracks[7].waveform='sine';}
 return p;
}
function renderLearning(){const term=nextUI('#learn-search').value.trim().toLowerCase(),cat=nextUI('#learn-category').value,shown=lessons.filter(l=>(cat==='all'||cat===l.cat||cat==='saved'&&learningState.saved.includes(l.id))&&[l.title,l.intro,l.body,l.task].join(' ').toLowerCase().includes(term));nextUI('#learn-progress').textContent=`已读 ${learningState.done.length} / ${lessons.length}`;nextUI('#learn-count').textContent=shown.length?`${shown.length} 条资料 · 练习会替换当前工程，可撤销`:'没有找到资料。试试其他关键词，或切换到全部资料。';const list=nextUI('#learn-cards');list.replaceChildren();for(const lesson of shown){const card=document.createElement('article');card.className='lesson-card';const label=document.createElement('span');label.className='eyebrow';label.textContent=categoryNames[lesson.cat];const title=document.createElement('h3');title.textContent=lesson.title;const intro=document.createElement('p');intro.className='lesson-intro';intro.textContent=lesson.intro;const body=document.createElement('p');body.textContent=lesson.body;const task=document.createElement('p');task.className='lesson-task';task.textContent='试一试 · '+lesson.task;const actions=document.createElement('div');actions.className='lesson-actions';for(const [key,text] of [['saved','收藏'],['done','已读']]){const b=document.createElement('button');b.className='text-btn';b.textContent=text;b.setAttribute('aria-pressed',learningState[key].includes(lesson.id));b.onclick=()=>{learningState[key]=learningState[key].includes(lesson.id)?learningState[key].filter(id=>id!==lesson.id):[...learningState[key],lesson.id];saveLearning();renderLearning();};actions.append(b);}if(lesson.exercise||lesson.preset){const load=document.createElement('button');load.className='outline-btn';load.textContent='载入练习';load.onclick=()=>{if(!confirm('载入练习会替换当前工程，可撤销。重要作品建议先导出备份。'))return;studio.replace(lesson.exercise?exerciseProject(lesson.exercise):makePreset(lesson.preset));nextUI('[data-view="compose"]').click();studio.toast('练习已载入，点击播放开始比较');};actions.append(load);}card.append(label,title,intro,body,task,actions);list.append(card);}}
nextUI('#learn-search').oninput=renderLearning;nextUI('#learn-category').onchange=renderLearning;renderLearning();
